"""Deterministic environment inventory; values are never read or printed (#59)."""

from __future__ import annotations

import ast
import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
NAME = re.compile(r"[A-Z][A-Z0-9_]+")
# Host inputs / generated subprocess settings, not operator-provided secrets.
INTERNAL = {
    "SYSTEMROOT": "Windows process bootstrap",
    "WINDIR": "Windows process bootstrap",
    "COMSPEC": "Windows shell path",
    "PATHEXT": "Windows executable lookup",
    "HOME": "isolated eval home, generated by runner",
    "USERPROFILE": "isolated eval home, generated by runner",
    "APPDATA": "isolated eval home, generated by runner",
    "LOCALAPPDATA": "isolated eval home, generated by runner",
    "TEMP": "OS temporary directory / isolated eval home",
    "TMP": "OS temporary directory / isolated eval home",
    "PATH": "subprocess executable lookup",
    "PYTHONUTF8": "generated eval subprocess encoding",
    "PYTHONIOENCODING": "generated eval subprocess encoding",
    "GIT_CONFIG_NOSYSTEM": "generated Git isolation flag",
    "GIT_CONFIG_GLOBAL": "generated Git isolation flag",
    "GIT_TERMINAL_PROMPT": "generated Git isolation flag",
    "GIT_AUTHOR_NAME": "generated synthetic memory commit identity",
    "GIT_AUTHOR_EMAIL": "generated synthetic memory commit identity",
    "GIT_AUTHOR_DATE": "generated deterministic memory commit timestamp",
    "GIT_COMMITTER_NAME": "generated synthetic memory commit identity",
    "GIT_COMMITTER_EMAIL": "generated synthetic memory commit identity",
    "GIT_COMMITTER_DATE": "generated deterministic memory commit timestamp",
    "LC_ALL": "generated Git locale",
    "API_SERVER_KEY": "generated private eval gateway secret; never user setup",
    "HERMES_SESSION_ID": "generated by isolated Hermes; not a session credential",
    "HERMES_DISABLE_LAZY_INSTALLS": "generated eval offline isolation flag",
    "CI": "CI-owned test runner flag",
    "INSPECT_LOGS": "CI-owned Inspect report output directory",
    "POSTGRES_PASSWORD": "throwaway CI PostgreSQL service password, never a deployment credential",
    "SERENE_FIXTURE_ROUTES": "test-only web build flag; omit in production",
    "PLAYWRIGHT_NO_COPY_PROMPT": "real-stack runner disables snapshots of credential forms",
}


def python_references(source: str) -> tuple[set[str], list[tuple[int, str]]]:
    tree = ast.parse(source)
    env_aliases = {"os.environ", "environ"}
    getters = {"os.getenv", "getenv"}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name == "os":
                    env_aliases.add(f"{alias.asname or 'os'}.environ")
                    getters.add(f"{alias.asname or 'os'}.getenv")
        elif isinstance(node, ast.ImportFrom) and node.module == "os":
            for alias in node.names:
                if alias.name == "environ":
                    env_aliases.add(alias.asname or alias.name)
                if alias.name == "getenv":
                    getters.add(alias.asname or alias.name)
    # Include aliases and copied environments (including frozen runner snapshots).
    for _ in range(4):
        for node in ast.walk(tree):
            if isinstance(node, ast.Assign) and (
                ast.unparse(node.value) in env_aliases
                or (
                    isinstance(node.value, ast.Call)
                    and ast.unparse(node.value.func) == "dict"
                    and any(ast.unparse(n) in env_aliases for n in node.value.args)
                )
            ):
                env_aliases.update(t.id for t in node.targets if isinstance(t, ast.Name))
    found: set[str] = set()
    dynamic: list[tuple[int, str]] = []
    for node in ast.walk(tree):
        key: ast.expr | None = None
        if isinstance(node, ast.Call):
            func = ast.unparse(node.func)
            if func in getters or any(
                func == f"{alias}.{method}"
                for alias in env_aliases
                for method in ("get", "pop", "setdefault")
            ):
                key = (
                    node.args[0]
                    if node.args
                    else next((kw.value for kw in node.keywords if kw.arg == "key"), None)
                )
        elif isinstance(node, ast.Subscript) and ast.unparse(node.value) in env_aliases:
            key = node.slice
        if key is not None:
            if isinstance(key, ast.Constant) and isinstance(key.value, str):
                found.add(key.value)
            else:
                dynamic.append((key.lineno, ast.unparse(node)))
        # Explicit sets used for indirect inherited[key] credential / OS reads.
        if isinstance(node, ast.Assign) and any(
            isinstance(t, ast.Name) and t.id in {"CREDENTIALS", "OS_INPUTS"} for t in node.targets
        ):
            found.update(
                n.value
                for n in ast.walk(node.value)
                if isinstance(n, ast.Constant)
                and isinstance(n.value, str)
                and NAME.fullmatch(n.value)
            )
        if isinstance(node, ast.FunctionDef) and node.name in {
            "_env",
            "_ident",
            "launch_environment",
        }:
            found.update(
                key.value
                for mapping in ast.walk(node)
                if isinstance(mapping, ast.Dict)
                for key in mapping.keys
                if isinstance(key, ast.Constant)
                and isinstance(key.value, str)
                and NAME.fullmatch(key.value)
            )
    return found, dynamic


def audit(root: Path = ROOT) -> list[str]:
    documented = {
        line.split("=", 1)[0].strip()
        for line in (root / ".env.example").read_text("utf-8").splitlines()
        if line and not line.startswith("#") and "=" in line
    }
    errors: list[str] = []
    internal = dict(INTERNAL)
    # Exact, frozen generated Hermes config bridges: not inherited setup inputs.
    # Their key/value bytes are also pinned by the synthetic provenance manifest.
    for name in ("hermes-v4-internal-bridges.json", "hermes-v5-internal-bridges.json"):
        path = root / "eval/fixtures" / name
        if path.is_file():
            internal.update(
                dict.fromkeys(
                    json.loads(path.read_text("utf-8")), f"generated Hermes config bridge in {name}"
                )
            )
    for folder in ("serene", "scripts", "eval", "tests", "app/web", "supabase", ".github"):
        for path in (root / folder).rglob("*"):
            if any(p in {"node_modules", ".next", "local", "__pycache__"} for p in path.parts):
                continue
            if path.suffix not in {
                ".py",
                ".ts",
                ".tsx",
                ".mts",
                ".mjs",
                ".ps1",
                ".sh",
                ".toml",
                ".yml",
                ".yaml",
            }:
                continue
            source = path.read_text("utf-8")
            if path.suffix == ".toml":
                source = "\n".join(
                    line for line in source.splitlines() if not line.lstrip().startswith("#")
                )
            rel = path.relative_to(root).as_posix()
            found: set[str] = set()
            if path.suffix == ".py":
                found, dynamic = python_references(source)
                # Frozen gateways compare/copy their complete launch environment.
                # Their finite OS_INPUTS/CREDENTIALS sets are inventoried above.
                reviewed = DYNAMIC_ENVIRONMENT_REVIEWS.get(rel, frozenset())
                errors.extend(
                    f"{rel}:{line}: dynamic env read needs review"
                    for line, expression in dynamic
                    if expression not in reviewed
                )
            else:
                if path.suffix in {".yml", ".yaml"}:
                    found.update(re.findall(r"\$\{?([A-Z][A-Z0-9_]+)\}?", source))
                    found.update(re.findall(r"\benv\.([A-Z][A-Z0-9_]+)", source))
                found.update(
                    re.findall(
                        r"(?:process\.env|import\.meta\.env|\benv)\.([A-Z][A-Z0-9_]+)", source
                    )
                )
                found.update(re.findall(r"""process\.env\[["']([A-Z][A-Z0-9_]+)["']\]""", source))
                found.update(re.findall(r"\$env:([A-Z][A-Z0-9_]+)", source))
                found.update(re.findall(r"\$\{([A-Z][A-Z0-9_]+):-", source))
                found.update(re.findall(r"\benv\(([A-Z][A-Z0-9_]+)\)", source))
            errors.extend(
                f"{rel}: undocumented {name}"
                for name in sorted(found - documented - internal.keys())
            )
    return errors


# Read-only audit of full-environment comparisons in frozen #67/#69 machinery.
# No generated/host values are setup requirements. New files fail closed.
DYNAMIC_ENVIRONMENT_REVIEWS = {
    path: frozenset({"current.pop(name, None)", "current.get(k)", "initial_environment.get(k)"})
    for path in ("eval/runners/live_gate4_gateway.py", "eval/runners/live_gate5_gateway.py")
}


def main() -> int:
    errors = audit()
    for error in errors:
        print(error)
    print(f"env coverage: {len(errors)} finding(s); internal/test variables explicitly classified")
    return bool(errors)


if __name__ == "__main__":
    sys.exit(main())
